    $scope.updateRecovery1EditPermissions = function () {

        const nurseStatus = $scope.PostOpObj.PostOpNurseChartStatus;
        const anesthesiaStatus = $scope.PostOpObj.PostOpAnesthesiaChartStatus;

        $scope.PostOpObj.IsNurseSectionsEdit = false;
        $scope.PostOpObj.IsShowNurseSummaryViewInd = true;
        $scope.PostOpObj.IsAnesthesiaSectionsEdit = false;

        //if ($scope.RoleId === ROLE.NURSE) {
        //    $scope.ActiveClinicalRole = 'NURSE';
        //}

        //if (ROLE.ANESTHESIA.includes($scope.RoleId)) {
        //    $scope.ActiveClinicalRole = 'ANESTHESIA';
        //}

        // NURSE SECTION
        const isNurse =
            $scope.RoleId === 8; // Nurse

        const isAnesthesiologist =
            $scope.RoleId === 25 || $scope.RoleId === 30;
        if (isNurse || isAnesthesiologist) {
            if (isNurse) {
                if (nurseStatus === '') {
                    $scope.PostOpObj.IsNurseSectionsEdit = true;
                    $scope.PostOpObj.IsShowNurseSummaryViewInd = false;
                }
                if (nurseStatus === 'D' && $scope.IsNurseExplicitEdit) {
                    $scope.PostOpObj.IsNurseSectionsEdit = true;
                    $scope.PostOpObj.IsShowNurseSummaryViewInd = false;
                } else if ($scope.IsNurseUnsignExplicitEdit) {
                    $scope.PostOpObj.IsNurseSectionsEdit = true;
                    $scope.PostOpObj.IsShowNurseSummaryViewInd = false;
                    $scope.IsNurseUnsignExplicitEdit = false;
                }
            }
            // ANESTHESIA SECTION
            else if (isAnesthesiologist) {
                if (anesthesiaStatus === '') {
                    $scope.PostOpObj.IsAnesthesiaSectionsEdit = true;
                }
                if (anesthesiaStatus === 'D' && $scope.IsAnesthesiaExplicitEdit) {
                    $scope.PostOpObj.IsAnesthesiaSectionsEdit = true;
                } else if ($scope.IsAnesthesiaUnsignExplicitEdit) {
                    $scope.PostOpObj.IsAnesthesiaSectionsEdit = true;
                    $scope.IsAnesthesiaUnsignExplicitEdit = false;

                }
            }
        } else {
            if ($scope.IsNurseSignValid || $scope.IsAnesthesiaSignValid || $scope.IsNurseExplicitEdit || $scope.IsAnesthesiaExplicitEdit) {
                if ($scope.IsNurseSignValid || $scope.IsNurseExplicitEdit) {
                    if (nurseStatus === '') {
                        $scope.PostOpObj.IsNurseSectionsEdit = true;
                        $scope.PostOpObj.IsShowNurseSummaryViewInd = false;
                    }
                    if (nurseStatus === 'D' && $scope.IsNurseExplicitEdit) {
                        $scope.PostOpObj.IsNurseSectionsEdit = true;
                        $scope.PostOpObj.IsShowNurseSummaryViewInd = false;
                    } else if ($scope.IsNurseUnsignExplicitEdit) {
                        $scope.PostOpObj.IsNurseSectionsEdit = true;
                        $scope.PostOpObj.IsShowNurseSummaryViewInd = false;
                        $scope.IsNurseUnsignExplicitEdit = false;
                    }
                }
                // ANESTHESIA SECTION
                if ($scope.IsAnesthesiaSignValid || $scope.IsAnesthesiaExplicitEdit) {
                    if (anesthesiaStatus === '') {
                        $scope.PostOpObj.IsAnesthesiaSectionsEdit = true;
                    }
                    if (anesthesiaStatus === 'D' && $scope.IsAnesthesiaExplicitEdit) {
                        $scope.PostOpObj.IsAnesthesiaSectionsEdit = true;
                    } else if ($scope.IsAnesthesiaUnsignExplicitEdit) {
                        $scope.PostOpObj.IsAnesthesiaSectionsEdit = true;
                        $scope.IsAnesthesiaUnsignExplicitEdit = false;
                    }
                }
            } else if (nurseStatus === '' || anesthesiaStatus === '') {
                if (nurseStatus === '') {
                    $scope.PostOpObj.IsNurseSectionsEdit = true;
                    $scope.PostOpObj.IsShowNurseSummaryViewInd = false;
                }
                if (anesthesiaStatus === '') {
                    $scope.PostOpObj.IsAnesthesiaSectionsEdit = true;
                }
            }


        }


    };

