    $scope.getTimesList = function () {

        $scope.SlotStartValues = [];


        //for (var i = 0; i < 24; i++) {
        //    if (i > 9) {
        //        $scope.SlotStartValues.push({ 'time': i });
        //    }
        //    else {
        //        $scope.SlotStartValues.push({ 'time': '0' + i });
        //    }
        //}

        //$scope.SlotEndValues = [];
        //for (var i = 0; i < 24; i++) {
        //    if (i > 9) {
        //        $scope.SlotEndValues.push({ 'time': i });
        //    } else {
        //        $scope.SlotEndValues.push({ 'time': '0' + i });
        //    }
        //}


        for (let hour = 6; hour < 24; hour++) {
            for (let minute = 0; minute < 60; minute += 10) {
                const formattedHour = hour.toString().padStart(2, '0');
                const formattedMinute = minute.toString().padStart(2, '0');
                $scope.SlotStartValues.push({ 'time': `${formattedHour}:${formattedMinute}` });
            }
        }

        angular.forEach($scope.SlotStartValues, function (item) {

            let tempArray = item.time.split(":");
            item.counter = tempArray.join("");
            item.counter = parseInt(item.counter);

            let dummydate = "2024-02-02";
            let dummydatetime = dummydate + " " + item.time;
            item.NewTime = moment(dummydatetime, "YYYY-MM-DD HH:mm").format("hh:mm A");
        });

    };

    $scope.getTimesList();

    $scope.getSlotEndTimesList = function (val) {
        var val = parseInt(val);
        val = val + 1;
        $scope.SlotEndValues = [];
        for (var i = val; i < 24; i++) {
            if (i > 9) {
                i = i.toString();
                $scope.SlotEndValues.push({ 'time': i });
            } else {
                $scope.SlotEndValues.push({ 'time': '0' + i });
            }
        }
    };

