    $scope.getOrgMedicines = function (text, val) {
        val = val || null;
        var req = {
            "HospitalId": $scope.HospitalId,
            "PageSize": 20,
            "SearchText": text || '',
            "PageNumber": 1,
            "UserId": $scope.UserId,
            "IsFrequent": "N",
            "MedTypeId": val,
            "ParentOrganizationId": $scope.ParenthospitalId || null
        };
        //if (req.SearchKey == "") {
        //    req.IsFrequent = "Y";
        //}

        return eHnoteConditionsDataService.GetOrganizationMedications(req).then(function (resp) {
            if (resp.data.count !== 0) {

                if (resp.data.MedicineList !== undefined) {
                    var list1 = [];
                    angular.forEach(resp.data.MedicineList, function (item) {
                        if (item.MedTypeId == val || item.MedTypeId == null) {
                            list1.push(item);
                        }
                    });
                    return list1.map(function (item) {
                        return item;

                    });
                }
            }
        });

    };
    $scope.isDisabledFields = false;
    $scope.CreateSlots = function () {
        $scope.AnesthesiaObj.AnesthesiaTypeId = $scope.AnesthesiaObj.AnesthesiaTypeId || '';
        $scope.AnesthesiaObj.Duration = $scope.AnesthesiaObj.Duration || '';

        //if ($scope.AnesthesiaObj.AnesthesiaTypeId == '') {
        //    alertify.error('Please select Anesthesia Type');
        //    return false;
        //}
        $scope.AnesthesiaObj.StartTime = $scope.AnesthesiaObj.StartTime || '';
        if ($scope.AnesthesiaObj.StartTime == '') {
            alertify.error('Please select Start Time');
            return false;
        }
        $scope.AnesthesiaObj.EndTime = $scope.AnesthesiaObj.EndTime || '';
        if ($scope.AnesthesiaObj.EndTime == '') {
            alertify.error('Please select End Time');
            return false;
        }
        if ($scope.AnesthesiaObj.Duration == '') {
            alertify.error('Please select duration!');
            return false;
        }

        var consultationTime = $scope.AnesthesiaObj.Duration;
        if (consultationTime != undefined) {
            var CurrentDate = $filter('date')(new Date(), 'MM-dd-yyyy');
            $scope.timeslots = [];

            var arr = $scope.AnesthesiaObj.StartTime.split(':');
            var shour = $.trim(arr[0]);
            var smin = $.trim(arr[1]);
            var arr2 = $scope.AnesthesiaObj.EndTime.split(':')
            var ehour = $.trim(arr2[0]);
            var emin = $.trim(arr2[1]);
            var startingTime = moment().hours(shour).minutes(smin);
            var endingTime = moment().hours(ehour).minutes(emin);

            var currentStartTime = angular.copy(startingTime);
            var token = 1;
            while (currentStartTime <= endingTime) {

                var slotObj = {
                    "StartTime": currentStartTime.format("HH:mm"),
                    "EndTime": currentStartTime.add(consultationTime, "minute").format("HH:mm"),
                    "TokenNumber": token,
                    "Available": "Y"
                }
                token++;
                var datetime = CurrentDate + "T" + slotObj.StartTime;
                slotObj.NewStartTime = "";
                slotObj.NewStartTime = $filter('date')(datetime, "hh:mm a");

                $scope.timeslots.push(slotObj);
            }
        }
        if ($scope.timeslots.length >= 13) {
            $scope.timeslots = [];
            $scope.AnesthesiaMedicines = [];
            alertify.error('Please select the Time In Between 12 Slots');
            return false;
        }

        if ($scope.timeslots.length > 0) {
            $scope.AnesthetistVitals1 = [];
            $scope.AldreteTotalScoreDetails = [];
            if ($scope.AnesthetistVitals.length > 0) {
                $scope.AnesthetistVitals = angular.copy($scope.GetAnesthetistVitals());
                angular.forEach($scope.AnesthetistVitals, function (item) {
                    for (var k = 0; k < $scope.timeslots.length; k++) {
                        var obj = {
                            "VitalValueId": 0,
                            "PostOPAnesthesiaVitalsId": 0,
                            "VitalName": item.VitalName,
                            "MainId": item.VitalId,
                            "VitalSlotTime": $scope.timeslots[k].StartTime,
                            "Value": "",
                            "DeleteInd": "N"

                        };
                        item.VitalValues.push(obj);
                        $scope.AnesthetistVitals1.push(obj);
                    }
                });
            }

            $scope.AldreteDetails = angular.copy($scope.GetAldreteDetails());
            angular.forEach($scope.AldreteDetails, function (item) {
                var count = 0;
                for (var k = 0; k < $scope.timeslots.length; k++) {
                    if (item.AldreteVitalId == 4) {
                        if (count == 0) {
                            var obj = {
                                "PatientPostOpAldreteValueId": null,
                                "PostOPAldreteDetailId": 0,
                                "AldreteVitalSlotTime": $scope.timeslots[k].StartTime,
                                "ValueId": item.AldreteVitalId,
                                "Score": "1",
                                "DeleteInd": "N"
                            };
                        } else {
                            var obj = {
                                "PatientPostOpAldreteValueId": null,
                                "PostOPAldreteDetailId": 0,
                                "AldreteVitalSlotTime": $scope.timeslots[k].StartTime,
                                "ValueId": item.AldreteVitalId,
                                "Score": "2",
                                "DeleteInd": "N"
                            };
                        }

                        count = count + 1;
                    } else {
                        var obj = {
                            "PatientPostOpAldreteValueId": null,
                            "PostOPAldreteDetailId": 0,
                            "AldreteVitalSlotTime": $scope.timeslots[k].StartTime,
                            "ValueId": item.AldreteVitalId,
                            "Score": "2",
                            "DeleteInd": "N"
                        };
                    }
                    item.AldreteValues.push(obj);
                }
            });

            var count1 = 0;
            for (var k = 0; k < $scope.timeslots.length; k++) {

                if (count1 == 0) {
                    $scope.AldreteTotalScoresObj = angular.copy($scope.GetAldreteTotalScoresObj());
                    $scope.AldreteTotalScoresObj.AldreteSlotTime = $scope.timeslots[k].StartTime;
                    $scope.AldreteTotalScoresObj.TotalScore = "11";
                    $scope.AldreteTotalScoreDetails.push($scope.AldreteTotalScoresObj);
                }
                else {
                    $scope.AldreteTotalScoresObj = angular.copy($scope.GetAldreteTotalScoresObj());
                    $scope.AldreteTotalScoresObj.AldreteSlotTime = $scope.timeslots[k].StartTime;
                    $scope.AldreteTotalScoresObj.TotalScore = "12";
                    $scope.AldreteTotalScoreDetails.push($scope.AldreteTotalScoresObj);
                }

                count1 = count1 + 1;
            }
        }

        let len = $("canvas#myChart").length;
        if (len > 0) {
            $("canvas#myChart").remove();
        }
        $scope.IsDisabled = false;
        $scope.PostOpObj.ShowGraph = true;
        $scope.AllowDistinctValues();
        $scope.isDisabledFields = true;
    };

