    $scope.GetTimeSlots1 = function (val) {
        /*    $scope.SlotValues = [];*/
        //for (var i = 0; i <= 59; i++) {
        //    if (i > 9) {
        //        $scope.SlotValues.push({ 'time': val + ':' + i });
        //    } else {
        //        $scope.SlotValues.push({ 'time': val + ':' + '0' + i });
        //    }
        //}

        //let nextVal = 0;
        //nextVal = parseInt(val) + 1;

        //if (nextVal === 24) {
        //    nextVal = 0;
        //}

        //if (nextVal > 9) {
        //    $scope.SlotValues.push({ 'time': nextVal + ':' + '00' });
        //} else {
        //    $scope.SlotValues.push({ 'time': '0' + nextVal + ':' + '00' });
        //}

        let dummydatetime = "2024-01-01" + " " + val;

        let startTime = moment(dummydatetime);
        let duration = 60; // 1 hour in minutes
        let timeDifference = 1; // 1 minute difference

        let slotTime;
        let formattedTime24;
        let formattedTime12;

        // Function to format time in 24-hour format
        function formatTime24(date) {
            return date.format("HH:mm");
        }

        // Function to format time in 12-hour format
        function formatTime12(date) {
            return date.format("hh:mm A");
        }

        for (let i = 0; i < 60; i++) {
            slotTime = moment(startTime).add(i * timeDifference, 'minutes');
            formattedTime24 = formatTime24(slotTime);
            formattedTime12 = formatTime12(slotTime);
            $scope.SlotValues.push({ 'time': formattedTime24, 'NewTime': formattedTime12 });
        }
        /*console.log($scope.SlotValues);*/
    };

    $scope.previousStartTime = null;

    $scope.GetTimeSlots = function (val) {
        if ($scope.SlotValues.length === 0) {
            $scope.previousStartTime = val;

            let dummydatetime = "2024-01-01" + " " + val;
            let startTime = moment(dummydatetime);
            let timeDifference = 1; // 1 minute difference

            let slotTime;
            let formattedTime24;
            let formattedTime12;

            // Function to format time in 24-hour format
            function formatTime24(date) {
                return date.format("HH:mm");
            }

            // Function to format time in 12-hour format
            function formatTime12(date) {
                return date.format("hh:mm A");
            }

            for (let i = 0; i < 60; i++) {
                slotTime = moment(startTime).add(i * timeDifference, 'minutes');
                formattedTime24 = formatTime24(slotTime);
                formattedTime12 = formatTime12(slotTime);
                $scope.SlotValues.push({ 'time': formattedTime24, 'NewTime': formattedTime12 });
            }

        } else {
            alertify.confirm(
                "<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre pl-20 pr-20'>Are you sure you want to replace the existing slots with the selected slot? </h4>",
                function () {
                    $scope.previousStartTime = val;

                    $scope.SlotValues = [];
                    $scope.additionalSlotsCount = 0;
                    let dummydatetime = "2024-01-01" + " " + val;

                    let startTime = moment(dummydatetime);
                    let timeDifference = 1; // 1 minute difference

                    let slotTime;
                    let formattedTime24;
                    let formattedTime12;

                    // Function to format time in 24-hour format
                    function formatTime24(date) {
                        return date.format("HH:mm");
                    }

                    // Function to format time in 12-hour format
                    function formatTime12(date) {
                        return date.format("hh:mm A");
                    }

                    for (let i = 0; i < 60; i++) {
                        slotTime = moment(startTime).add(i * timeDifference, 'minutes');
                        formattedTime24 = formatTime24(slotTime);
                        formattedTime12 = formatTime12(slotTime);
                        $scope.SlotValues.push({ 'time': formattedTime24, 'NewTime': formattedTime12 });
                    }
                    $scope.$digest();
                },
                function () {
                    $scope.AnesthesiaObj.StartTime = $scope.previousStartTime;
                    $scope.$digest();
                }
            );
        }

        console.log($scope.SlotValues);
    };



    $scope.AddNewTimeSlot = function () {
        if ($scope.additionalSlotsCount < 4) {
            let lastSlot = $scope.SlotValues[$scope.SlotValues.length - 1];
            let lastTime = moment("2024-01-01" + " " + lastSlot.time);
            let newStartTime = lastTime.add(1, 'minutes');

            $scope.AnesthesiaObj.EndTime = newStartTime.format("HH:mm");

            for (let i = 0; i < 60; i++) {
                let slotTime = moment(newStartTime).add(i, 'minutes');
                let formattedTime24 = slotTime.format("HH:mm");
                let formattedTime12 = slotTime.format("hh:mm A");
                $scope.SlotValues.push({ 'time': formattedTime24, 'NewTime': formattedTime12 });
            }

            $scope.additionalSlotsCount++;
            /*$scope.$digest();*/
        }
    };

    $scope.toDataURL = function (dataURL, callback) {
        var xhr = new XMLHttpRequest();
        xhr.onload = function () {
            var reader = new FileReader();
            reader.onloadend = function () {
                callback(reader.result);
            };
            reader.readAsDataURL(xhr.response);
        };
        xhr.open('GET', dataURL);
        xhr.responseType = 'blob';
        xhr.send();
    };
