    $scope.matchFilter = function (val, val1) {
        $scope.AnesthetistVitals1 = $scope.AnesthetistVitals1 || [];
        if ($scope.AnesthetistVitals1.length > 0) {
            var tempArray = [];
            tempArray = $scope.AnesthetistVitals1.filter(function (hitem) {
                hitem.Value = hitem.Value || "";
                if (hitem.Value !== "") {
                    return (parseInt(hitem.Value) <= (val + val1)) && (parseInt(hitem.Value) > val);
                }
            });
            return tempArray;
        }

    };

    $scope.AllowDistinctValues = function (obj) {
        obj = obj || "";
        if (obj != "") {
            if (obj.Score != '0') {
                obj.Score = obj.Score || null;
                if (obj.Score != null) {
                    if (obj.Score != '0' && obj.Score != '1' && obj.Score != '2') {
                        alertify.error("Please enter valid value!");
                        obj.Score = null;
                    }
                } else {
                    obj.Score = null;
                }
            }
        }

        // calculate aggregate value for the time slot and assign to total array
        let sum = 0;
        angular.forEach($scope.AldreteDetails, function (kitem) {
            angular.forEach(kitem.AldreteValues, function (item) {
                if (item.AldreteVitalSlotTime === obj.AldreteVitalSlotTime) {
                    if (item.Score != 0) {
                        item.Score = item.Score || null;
                    }
                    if (item.Score != null) {
                        sum += parseInt(item.Score);
                    }
                }
            });
        });

        angular.forEach($scope.AldreteTotalScoreDetails, function (hitem) {
            if (hitem.AldreteSlotTime === obj.AldreteVitalSlotTime) {
                hitem.TotalScore = sum;
            }
        });

    };


