    $scope.selectPostOpImgs = function (files) {

        files = files || [];
        if (files.length > 0) {
            angular.forEach(files, function (item) {
                $scope.file = item;
                if ($scope.file != null) {

                    var pName = $scope.file.name, name = "";
                    var type = $scope.file.type.split("/")[1];
                    if (pName.length > 9) {
                        name = pName.substring(0, 9) + "..." + "." + type;
                    } else {
                        name = angular.copy(pName) + '.' + type;
                    }
                    var obj = {
                        "file": $scope.file,
                        "DocumentID": 0,
                        "DisplayName": $scope.file.name || "",
                        "FileName": $scope.file.name || "",
                        "FileExt": $scope.file.type,
                        "S3URL": "",
                        "DeleteInd": false,
                        "FileTypeId": 22,
                    };

                    $scope.FilesObj.TempImagesArray.push(obj);

                    angular.element("input[type='file']").val(null);
                }
            });
        }
    };

    $scope.DeletePostOpFiles = function (item, index) {
        if (item.DocumentID == 0) {
            $scope.FilesObj.TempImagesArray.splice(index, 1);
        }
    }

    $scope.GetPostOpChartData = function () {
        let params = {
            "OrganizationId": $scope.HospitalId,
            "AppointmentId": $scope.cacheStorageItem.AppointmentId || null,
            "PatientId": $scope.cacheStorageItem.PatientID || null,
            "PatientSurgeryId": $scope.SurgeryDiagnosisObj.SelectedSurgery.PatientSurgeryId
        };
        eHnoteSurgeryService.GetPostOpChartData(params).then(function (resp) {
            if (resp.data.Status == "Success") {
                // $scope.GenerateSasURL(resp.data);

                $scope.PostOpObj.DischargeSignOffStartTime = resp.data.DischargeSignOffStartTime || '';
                $scope.PostOpObj.DischargeSignOffEndTime = resp.data.DischargeSignOffEndTime || '';
                $scope.PostOpObj.DischargeStartTimeUser = resp.data.DischargeStartTimeUser || null;
                $scope.PostOpObj.DischargeEndTimeUser = resp.data.DischargeEndTimeUser || null;
                $scope.PostOpObj.DischargeStopTimerRemarks = resp.data.DischargeStopTimerRemarks || null;

                $scope.PostOpObj.DischargeTimeId = resp.data.DischargeTimeId || 0;
                $scope.PostOpObj.DischargeTime = resp.data.DischargeTime || "";

                $scope.PostOpObj.IsForceEarlySignOff = resp.data.IsForceEarlySignedOff || false;

                $scope.PostOpObj.IsShowForceEarlySignOffButton = false;

                //if ($scope.PostOpObj.DischargeSignOffStartTime !== '' && $scope.PostOpObj.DischargeSignOffEndTime !== '') {
                //    $scope.PostOpObj.IsShowForceEarlySignOffButton = false;
                //} else if ($scope.PostOpObj.DischargeSignOffStartTime !== '') {
                //    const now = new Date();
                //    const timeStr = $scope.PostOpObj.DischargeSignOffStartTime;
                //    if (timeStr && typeof timeStr === 'string' && timeStr.includes(":")) {
                //        const time24 = convertTo24Hour(timeStr);
                //        const parsedStartTime = new Date(`1970-01-01T${time24}:00`);
                //        const startTime = new Date(now);
                //        startTime.setHours(parsedStartTime.getHours(), parsedStartTime.getMinutes(), 0, 0);
                //        if (startTime > now) {
                //            startTime.setDate(startTime.getDate() - 1);
                //        }
                //        const diffMs = now - startTime;
                //        const totalMinutes = Math.floor(diffMs / (1000 * 60));
                //        var timeDifferenceInMinutes = totalMinutes;

                //        var DischargeTime = parseFloat($scope.PostOpObj.DischargeTime);

                //        if (timeDifferenceInMinutes >= DischargeTime) {
                //            $scope.PostOpObj.IsShowForceEarlySignOffButton = false;
                //        } else {
                //            if ($scope.PostOpObj.DischargeSignOffEndTime == '') {
                //                $scope.PostOpObj.IsShowForceEarlySignOffButton = true;
                //            } else {
                //                $scope.PostOpObj.IsShowForceEarlySignOffButton = false;
                //            }
                //        }
                //    }
                //}

                //if ($scope.PostOpObj.DischargeSignOffStartTime !== '' && $scope.PostOpObj.DischargeSignOffEndTime == '') {
                //    $scope.ShowTimer($scope.PostOpObj.DischargeSignOffStartTime, $scope.PostOpObj.DischargeTime);
                //} else {
                //    if ($scope.PostOpObj.DischargeSignOffEndTime !== '') {
                //        $scope.PostOpObj.DischargeTimerStartTime = $scope.PostOpObj.DischargeSignOffEndTime;
                //    } else {
                //        $scope.PostOpObj.DischargeTimerStartTime = '';
                //    }
                //}
                if ($scope.PostOpObj.DischargeTime !== '') {
                    if ($scope.PostOpObj.IsForceEarlySignOff) {
                        $scope.PostOpObj.IsShowForceEarlySignOffButton = false;
                        $scope.PostOpObj.DischargeTimerStartTime = $scope.PostOpObj.DischargeSignOffEndTime;
                        $scope.PostOpObj.IsTimerStoped = true;
                    } else if ($scope.PostOpObj.DischargeSignOffStartTime !== '') {
                        const now = new Date();
                        const timeStr = $scope.PostOpObj.DischargeSignOffStartTime;
                        if (timeStr && typeof timeStr === 'string' && timeStr.includes(":")) {
                            const time24 = convertTo24Hour(timeStr);
                            const parsedStartTime = new Date(`1970-01-01T${time24}:00`);
                            const startTime = new Date(now);
                            startTime.setHours(parsedStartTime.getHours(), parsedStartTime.getMinutes(), 0, 0);
                            if (startTime > now) {
                                startTime.setDate(startTime.getDate() - 1);
                            }
                            const diffMs = now - startTime;
                            const totalMinutes = Math.floor(diffMs / (1000 * 60));
                            var timeDifferenceInMinutes = totalMinutes;

                            var DischargeTime = parseFloat($scope.PostOpObj.DischargeTime);

                            if (timeDifferenceInMinutes >= DischargeTime) {
                                $scope.PostOpObj.DischargeTimerStartTime = $scope.PostOpObj.DischargeSignOffEndTime;
                                $scope.PostOpObj.IsTimerStoped = true;
                                $scope.PostOpObj.IsShowForceEarlySignOffButton = false;
                            } else {
                                $scope.PostOpObj.IsShowForceEarlySignOffButton = true;
                                $scope.ShowTimer($scope.PostOpObj.DischargeSignOffStartTime, $scope.PostOpObj.DischargeTime);
                            }
                        }
                    }
                } else if ($scope.PostOpObj.DischargeSignOffStartTime !== '' && $scope.PostOpObj.DischargeSignOffEndTime !== '') {
                    $scope.PostOpObj.IsTimerStoped = true;
                }

                if (resp.data.rows.length > 0) {
                    $scope.PostOpObj.DocumentDetails = angular.copy(resp.data.rows[0].DocumentDetails);
                }
                $scope.PostOpObj.LastSignOffUserDetails = resp.data.LastSignOffUserDetails || [];
            }
        }, function (err) {
            alertify.error("Fetching Data failed!");
            console.log(err);
        });
    }

    $scope.scanFiles = function (item) {

        item = item || "";
        if (item == 1) {
            $scope.SelectedFile = 22;
        } else if (item == 2) {
            $scope.SelectedFile = 23;
        } else if (item == 3) {
            $scope.SelectedFile = 24;
        } else {
            $scope.SelectedFile = 25;
        }

        let PatientSurgeryId = null;
        if ($scope.cacheStorageItem.AppointmentTypeId == 4 || $scope.cacheStorageItem.AppointmentTypeId == 14) {
            if ($scope.cacheStorageItem.SurgeryList.length > 0) {
                PatientSurgeryId = $scope.cacheStorageItem.SurgeryList[0].PatientSurgeryId;
            }
        }
        if ($scope.cacheStorageItem.AppointmentTypeId == 7) {
            if ($scope.cacheStorageItem.PreAdmSurgeryList.length > 0) {
                PatientSurgeryId = $scope.cacheStorageItem.PreAdmSurgeryList[0].PatientSurgeryId;
            }
        }

        var obj = {
            "PatientId": $scope.cacheStorageItem.PatientID || null,
            "AppointmentId": $scope.cacheStorageItem.AppointmentId || null,
            "PatientName": $scope.MainObj.PatientDetails.FullName || '',
            "Tab": "ASCFileUploads",
            "SignedDate": $filter('date')($scope.currentDate, "yyyy-MM-dd"),
            "FileTypeId": parseInt($scope.SelectedFile),
            "FileName": '',
            "DisplayName": '',
            "PatientSurgeryId": PatientSurgeryId
        }

        $scope.mInstanceAdd = $uibModal.open({
            "templateUrl": "templates/UsNewConsultation/uibpopup/PatientDocumentScanner.html",
            "backdrop": "static",
            "scope": $scope,
            "size": "lg",
            "resolve": {
                "mainObject": function () { return obj; }
            },
            "windowClass": "modal__eighty--  ",
            "keyboard": false,
            "controller": "DocumentScannerCtrl",
        });
        $scope.mInstanceAdd.result.then(function (data) {
            console.log(data);
            if (data[0].Status == "Success") {
                $scope.GetPostOpChartData();
            }
        }, function (cancel) {
        });
    }

    $scope.DeletePostOpDocumentlist = function (item) {

        $scope.DeleteFileUploadArray = { "DocumentID": item.FileId, "FileName": item.FileName, "Remarks": "" };
        alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure you want to delete? </h4>", function () {
            var params = {
                "AppointmentID": $scope.cacheStorageItem.AppointmentId,
                "DeleteIndicator": 0,
                "ImagesArray": [],
                "UploadType": "Delete",
                "HospitalID": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
                "Remarks": ""
            };

            params.ImagesArray.push($scope.DeleteFileUploadArray);
            eHnoteDiagnosisDataServices.DeleteASCDocumentList(params, onupdateDeletesuccess, onupdateDelerror);
        }, function () { });
        function onupdateDeletesuccess(response) {
            if (response.Status === 'Success') {
                $scope.GetPostOpChartData();
            }
        }
        function onupdateDelerror(errordata) {
            console.log(errordata);
        }
    }

