                    if (Type == 'ConnectWithPatient') {
                        $scope.PostOpCallObj.IsConnectedWithPatient = !$scope.PostOpCallObj.IsConnectedWithPatient;
                    }
                    if (Type == 'ConnectWithFamily') {
                        $scope.PostOpCallObj.IsConnectedWithFamilyOrFriend = !$scope.PostOpCallObj.IsConnectedWithFamilyOrFriend;
                    }
                    if (Type == 'LeftMsgWithPatient') {
                        $scope.PostOpCallObj.IsLeftMsgWithPatient = !$scope.PostOpCallObj.IsLeftMsgWithPatient;
                    }
