                        "IsNoAlcoholFor24Hours": $scope.PostOpCallObj.IsNoAlcoholFor24Hours,
                        "IsDoNotRubTheEye": $scope.PostOpCallObj.IsDoNotRubTheEye,
                        "IsCallTheClinicForAnyComplications": $scope.PostOpCallObj.IsCallTheClinicForAnyComplications,
                        "IsCall911orGoToNearestER": $scope.PostOpCallObj.IsCall911orGoToNearestER,
                        "IsOther": $scope.PostOpCallObj.IsOther,
                        "InstructionSharedWithPatient": $scope.PostOpCallObj.InstructionSharedWithPatient,
                        "IsPatientDoingWell": $scope.PostOpCallObj.IsPatientDoingWell,
                        "IsPatientMildDisComfort": $scope.PostOpCallObj.IsPatientMildDisComfort,
                        "IsPatientModerateDisComfort": $scope.PostOpCallObj.IsPatientModerateDisComfort,
