    $scope.UnSignPostOp = function () {

        let modalInstance = $uibModal.open({
            "templateUrl": "UnSignRemarksPopUp.html",
            "controller": function ($scope, $uibModal, $uibModalInstance) {

                $scope.Obj = {
                    "Remarks": ""
                };

                $scope.ClosePopup = function () {
                    $uibModalInstance.dismiss("cancel");
                };

                $scope.Unsign = function () {

                    if ($scope.Obj.Remarks === "") {
                        alertify.error("Please enter remarks!");
                        return;
                    }

                    let obj = {
                        "AppointmentId": $scope.cacheStorageItem.AppointmentId,
                        "PatientId": $scope.cacheStorageItem.PatientID,
                        "UserId": $scope.UserId,
                        "PatientASCPreOPId": 0,
                        "PatientASCIntraOPId": 0,
                        "PatientASCPostOPId": $scope.PostOpObj.PatientASCPostOPId,
                        "StatusFlag": "E",
                        "Remarks": $scope.Obj.Remarks,
                        "Type": "PostOp" // "IntraOp", "PostOp"
                    };

                    eHnoteMainAppointmentService.AddAscUnsignDataLog(obj).then(function (resp) {
                        if (resp.data.Status === "Success") {
                            $uibModalInstance.close("close");
                        }
                    }, function (err) {
                        console.log(err);
                    });

                };

            },
            "size": "md",
            "backdrop": "static",
            "scope": $scope,
            "keyboard": false
        });
        modalInstance.result.then(function (data) {
            $scope.PostOpObj.IsEdit = true;
            $scope.PostOpObj.IsShow = false;
            $scope.PostOpObj.IsShowPostOpSummaryViewInd = false;
            $scope.init();
        }, function (cancel) {

        });
    };


