    $scope.AddChecklistTemplateDischargeSummary = function (val) {
        let modalInstance = $uibModal.open({
            "templateUrl": "templates/uibpopups/ChecklistTemplateNamePopUp.html",
            "controller": function ($scope, $uibModalInstance, CheckListCategoryId) {
                $scope.closePopup = function () {
                    $uibModalInstance.dismiss("cancel");
                };

                $scope.SaveTemplateName = function () {
                    $scope.TemplateName = $scope.TemplateName || "";

                    if ($scope.TemplateName === "") {
                        alertify.error("Please enter template name!");
                        return false;
                    }
                    $scope.TemplateDetails = [];
                    var PreOpDischargeSummaryobj = {
                        "DischargeMedicationInstructions": $scope.DischargeSummaryObj.DischargeMedicationInstructions || "",
                        "PostOpInstruction": $scope.DischargeSummaryObj.PostOpInstruction || "",
                        "Medicationslist": $scope.DischargeSummaryObj.Medications || []
                    }
                    $scope.TemplateDetails.push(PreOpDischargeSummaryobj);
                    let templateReq = {
                        "UserId": $scope.UserId,
                        "PostOpDischargeSummaryTemplateId": 0,
                        "PostOpDischargeSummaryTemplateDetails": $scope.TemplateDetails || [],
                        "TemplateName": $scope.TemplateName,
                        "DeleteInd": "N",
                    };
                    eHnoteSurgeryService.AddUpdateAscPostOpDischargeSummaryTemplates(templateReq).then(function (resp) {
                        if (resp.data.Status === "Success") {
                            alertify.success("Template saved successfully!");
                            $scope.GetAscPostOpDischargeSummaryTemplatesList();
                            $uibModalInstance.close();
                        }
                        if (resp.data.status === "Failure") {
                            alertify.error(resp.data.Message)
                        }
                    }, function (err) {
                        console.log(err);
                    });
                };
            },
            "backdrop": "static",
            "keyboard": false,
            "size": "sm",
            "scope": $scope,
            "resolve": {
                "CheckListCategoryId": function () {
                    return val;
                }
            }
        });
        modalInstance.result.then(function (data) {
        }, function (data) {
            console.log(data);
        });
    };
    $scope.GetAscPostOpDischargeSummaryTemplatesList = function () {
        //let gettemplateReq = {
        //    "UserId": $scope.UserId,
        //};
        eHnoteSurgeryService.GetAscPostOpDischargeSummaryTemplatesList($scope.UserId).then(function (resp) {
            if (resp.data.Status === "Success") {
                $scope.AscPostOpDischargeSummaryTemplateList = [];
                $scope.AscPostOpDischargeSummaryTemplateList = resp.data.PreOpDischargeSummaryTemplate;
            }
            if (resp.data.status === "Failure") {
                alertify.error(resp.data.Message)
            }
        }, function (err) {
            console.log(err);
        });
    };
