    $scope.SaveDischargeSummaryTemplate = function (type) {

        if (type != '') {
            var PatientId = $scope.cacheStorageItem.PatientID || "";
            var AppointmentId = $scope.cacheStorageItem.AppointmentId || "";
            if (type.PostOpDischargeSummaryTemplateDetails != '') {
                var CurrentMedicationslist = type.PostOpDischargeSummaryTemplateDetails[0].Medicationslist || [];
                var PostOpInstruction = type.PostOpDischargeSummaryTemplateDetails[0].PostOpInstruction || "";
                var DischargeMedicationInstructions = type.PostOpDischargeSummaryTemplateDetails[0].DischargeMedicationInstructions || "";
            }
            let req = {
                "PatientDischargeSummaryId": 0,
                "PatientId": PatientId || null,
                "AppointmentId": AppointmentId || null,
                "MedicationList": CurrentMedicationslist || [],
                "DischargeMedicationInstructions": DischargeMedicationInstructions || "",
                "PostOpInstructions": PostOpInstruction || "",
                "FollowUpDate1": "",
                "FollowUpDate2": "",
                "FollowUpDate3": "",
                "FollowUpInstructions": ""
            };
            eHnoteSurgeryService.AddUpdateDischargeSummaryDetails(req).then(function (resp) {
                if (resp.data.Status === "Success") {
                    $scope.GetDischargeSummaryDetails();
                    //$scope.DischargeSummaryObj.DischargeSummaryTemplateName = '';
                }
            }, function () {

            });
        }
    };
    $scope.OnselectDischargeSummaryTemplates = function (type) {
        type = type || '';
        if (type != '') {
            $scope.SaveDischargeSummaryTemplate(type);
        }
    }

