    $scope.CopyAnesthetistGraphValuesByColumnWise = function () {
        if ($scope.AnesthetistVitals.length > 0) {
            angular.forEach($scope.AnesthetistVitals, function (item) {
                if (item.VitalId == 1) {
                    angular.forEach(item.VitalValues, function (vital) {
                        if (vital.Value !== '') {
                            $scope.AnesthesiaGraphObj.SystolicValue = vital.Value;
                        }
                    });
                }
                if (item.VitalId == 2) {
                    angular.forEach(item.VitalValues, function (vital) {
                        if (vital.Value !== '') {
                            $scope.AnesthesiaGraphObj.DiastolicValue = vital.Value;
                        }
                    });
                }
                if (item.VitalId == 3) {
                    angular.forEach(item.VitalValues, function (vital) {
                        if (vital.Value !== '') {
                            $scope.AnesthesiaGraphObj.PulseValue = vital.Value;
                        }
                    });
                }
                if (item.VitalId == 4) {
                    angular.forEach(item.VitalValues, function (vital) {
                        if (vital.Value !== '') {
                            $scope.AnesthesiaGraphObj.RespValue = vital.Value;
                        }
                    });
                }
                if (item.VitalId == 5) {
                    angular.forEach(item.VitalValues, function (vital) {
                        if (vital.Value !== '') {
                            $scope.AnesthesiaGraphObj.SpO2Value = vital.Value;
                        }
                    });
                }
                if (item.VitalId == 6) {
                    angular.forEach(item.VitalValues, function (vital) {
                        if (vital.Value !== '') {
                            $scope.AnesthesiaGraphObj.O2SatValue = vital.Value;
                        }
                    });
                }
                if (item.VitalId == 7) {
                    angular.forEach(item.VitalValues, function (vital) {
                        if (vital.Value !== '') {
                            $scope.AnesthesiaGraphObj.ECGValue = vital.Value;
                        }
                    });
                }
                if (item.VitalId == 8) {
                    angular.forEach(item.VitalValues, function (vital) {
                        if (vital.Value !== '') {
                            $scope.AnesthesiaGraphObj.ETCO2Value = vital.Value;
                        }
                    });
                }
            });
        }
    }

