    $scope.Clearvalues = function (item) {
        console.log(item);
        console.log($scope.AnesthetistVitals);
        console.log($scope.AldreteTotalScoreDetails);
        alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are You Sure Want to Clear? </h4>", function () {
            if ($scope.AnesthetistVitals.length > 0) {
                angular.forEach($scope.AnesthetistVitals, function (Aitem) {
                    if (Aitem.VitalValues.length > 0) {
                        let temparray = $filter("filter")(Aitem.VitalValues, function (kitem, index) { return kitem.VitalSlotTime == item.time });
                        if (temparray.length > 0) {
                            temparray[0].Value = '';
                        }
                    }
                });
                $scope.$digest();
            }
        }, function () {
            return;
        });
    }
    $scope.DeleteVitalvalues = function (item) {
        alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are You Sure Want to Delete? </h4>", function () {

            if ($scope.AnesthetistVitals.length > 0) {
                angular.forEach($scope.AnesthetistVitals, function (Aitem) {
                    let temparray = $filter("filter")(Aitem.VitalValues, function (kitem, index) { return kitem.VitalSlotTime == item.time && kitem.DeleteInd == 'N' }) || [];
                    if (temparray.length > 0) {
                        temparray[0].PostOPAnesthesiaVitalsId = temparray[0].PostOPAnesthesiaVitalsId || 0;
                        if (temparray[0].PostOPAnesthesiaVitalsId != 0) {
                            temparray[0].DeleteInd = 'Y';
                        } else {
                            let index = Aitem.VitalValues.findIndex(vital => vital.VitalSlotTime === item.time && vital.DeleteInd == 'N');
                            if (index !== -1) {
                                Aitem.VitalValues.splice(index, 1);
                            }
                        }
                    }

                })
            }
            if ($scope.AldreteDetails.length > 0) {
                angular.forEach($scope.AldreteDetails, function (Aitem) {
                    let temparray = $filter("filter")(Aitem.AldreteValues, function (kitem, index) { return kitem.AldreteVitalSlotTime == item.time && kitem.DeleteInd == 'N' }) || [];
                    if (temparray.length > 0) {
                        temparray[0].PostOPAldreteDetailId = temparray[0].PostOPAldreteDetailId || 0;
                        if (temparray[0].PostOPAldreteDetailId != 0) {
                            temparray[0].DeleteInd = 'Y';
                        } else {
                            let index = Aitem.AldreteValues.findIndex(vital => vital.AldreteVitalSlotTime === item.time && vital.DeleteInd == 'N');
                            if (index !== -1) {
                                Aitem.AldreteValues.splice(index, 1);
                            }
                        }
                    }
                })
            }
            if ($scope.AldreteTotalScoreDetails.length > 0) {
                let temparray = $filter("filter")($scope.AldreteTotalScoreDetails, function (kitem, index) { return kitem.AldreteSlotTime == item.time && kitem.DeleteInd == 'N' }) || [];
                if (temparray.length > 0) {
                    temparray[0].PostOPAnesthesiaTotalScoreId = temparray[0].PostOPAnesthesiaTotalScoreId || 0;
                    if (temparray[0].PostOPAnesthesiaTotalScoreId != 0) {
                        temparray[0].DeleteInd = 'Y';
                    } else {
                        let index = $scope.AldreteTotalScoreDetails.findIndex(vital => vital.AldreteSlotTime === item.time && vital.DeleteInd == 'N');
                        if (index !== -1) {
                            $scope.AldreteTotalScoreDetails.splice(index, 1);
                        }
                    }
                }

            }
            if ($scope.NewTimeSlots.length > 0) {
                let index = $scope.NewTimeSlots.findIndex(vital => vital.time == item.time);
                if (index !== -1) {
                    $scope.NewTimeSlots.splice(index, 1);
                }

                // make lastbutoneIND false for all objects first before making it true for second from last object
                if ($scope.NewTimeSlots.length > 0) {
                    $scope.NewTimeSlots.forEach((x) => x.lastbutoneIND = false);
                }

                if ($scope.NewTimeSlots.length == 2 || $scope.NewTimeSlots.length > 2) {
                    $scope.NewTimeSlots[$scope.NewTimeSlots.length - 2].lastbutoneIND = true;
                }

                let filteredData = $filter('orderBy')($scope.NewTimeSlots, 'counter');
                if (filteredData.length > 0) {
                    $scope.PostOpObj.InTime = filteredData[0].NewTime || "";
                    $scope.PostOpObj.OutTime = filteredData[filteredData.length - 1].NewTime;
                    $scope.PostOpObj.RecoveryStopTime = filteredData[filteredData.length - 1].NewTime;
                    $scope.PostOpObj.Recovery1Outtime =  filteredData[filteredData.length - 1].NewTime;
                }

            }

            if ($scope.NewTimeSlots.length === 0) {
                $scope.PostOpObj.InTime = "";
                $scope.PostOpObj.OutTime = "";
                $scope.PostOpObj.RecoveryStopTime = "";
            }
            $scope.$digest();
        }, function () {
            return;
        });
    }

