            "Diagnosis": $scope.PostOpObj.Diagnosis || [],
            "TempDocumentDetails": [],
            "DocumentDetails": [],
            "InvestigationsList": [],
            //"AnesthesiaTypelist": $scope.PostOpObj.AnesthesiaTypelist,
