    $scope.SetTimeByLatestSlot = function () {
        var matchedSlot = null;
        if ($scope.NewTimeSlots && $scope.NewTimeSlots.length > 0) {   
            matchedSlot = $scope.NewTimeSlots[$scope.NewTimeSlots.length - 1];
        }
        if (matchedSlot) {
            $scope.PostOpObj.Recovery1Outtime = matchedSlot.NewTime;
        } else {
            $scope.PostOpObj.Recovery1Outtime = null;
        }
    };

    $scope.OnSelectTimeSlot = function (val) {

        let counter = 0;
        angular.forEach($scope.AnesthetistVitals, function (item) {
            let tempArray = $filter('filter')(item.VitalValues, { 'VitalSlotTime': val, "DeleteInd": 'N' }, true);
            if (tempArray.length > 0) {
                counter++;
            }
        });

        if (counter > 0) {
            alertify.error("Data already added!");
            return;
        }

        let Anestcounter1 = 0;
        angular.forEach($scope.AnesthetistVitals, function (item) {
            if (item.VitalValues.length > 0) {
                let lastObject = item.VitalValues[item.VitalValues.length - 1];
                lastObject.Value = lastObject.Value || '';
                if (lastObject.Value == '' && lastObject.DeleteInd == 'N') {
                    Anestcounter1++;
                }
            }
        });
        //if (Anestcounter1 == 5) {
        //    alertify.error("Please enter value.");
        //    return false;
        //}

        let Anestcounter2 = 0;
        angular.forEach($scope.AnesthetistVitals, function (item) {
            if (item.VitalValues.length > 0) {
                let firstObject = item.VitalValues[0];
                firstObject.Value = firstObject.Value || '';
                if (firstObject.Value == '' && firstObject.DeleteInd == 'N') {
                    Anestcounter2++;
                }
            }
        });
        //if (Anestcounter2 == 5) {
        //    alertify.error("Please enter value.");
        //    return false;
        //}

        $scope.AnesthesiaGraphObj = angular.copy($scope.GetAnesthesiaGraphObj());
        $scope.AnesthesiaGraphObj.SelectedTimeSlot = val;
        /*$scope.AnesthesiaGraphObj.ShowVitalParams = true;*/
        $scope.AddAnesthesiaVitalParameters();

        $scope.SetTimeByLatestSlot();
    };

    $scope.AldreteTotalScoreDetails = [];

    $scope.onAlderetScoreChange = function () {

        let val1 = 0; let val2 = 0; let val3 = 0; let val4 = 0; let val5 = 0; let val6 = 0;

        if ($scope.AnesthesiaGraphObj.PhysicalActivityValue != "") {
            val1 = parseInt($scope.AnesthesiaGraphObj.PhysicalActivityValue);
        }
        if ($scope.AnesthesiaGraphObj.RespirationValue != "") {
            val2 = parseInt($scope.AnesthesiaGraphObj.RespirationValue);
        }
        if ($scope.AnesthesiaGraphObj.CirculationsValue != "") {
            val3 = parseInt($scope.AnesthesiaGraphObj.CirculationsValue);
        }
        if ($scope.AnesthesiaGraphObj.ConciousnessValue != "") {
            val4 = parseInt($scope.AnesthesiaGraphObj.ConciousnessValue);
        }
        if ($scope.AnesthesiaGraphObj.AlderetSpO2Value != "") {
            val5 = parseInt($scope.AnesthesiaGraphObj.AlderetSpO2Value);
        }
        if ($scope.AnesthesiaGraphObj.ColorValue != "") {
            val6 = parseInt($scope.AnesthesiaGraphObj.ColorValue);
        }

        let sum = 0;
        sum += val1 + val2 + val3 + val4 + val5 + val6;

        $scope.AnesthesiaGraphObj.TotalScore = sum;
    }

