    // patient goals functionality

    // bringing default data from checklist service in init function

    $scope.OnSelectAllPatientGoallist = function (val) {
        if (val === 1) {
            if ($scope.PostOpObj.IsAllActionCheckListCheckedGoal == null || $scope.PostOpObj.IsAllActionCheckListCheckedGoal == 2) {
                $scope.PostOpObj.IsAllActionCheckListCheckedGoal = 1;
                angular.forEach($scope.PostOpObj.MasterAscPatientGoal, function (item) {
                    item.Value = "Yes";
                });
            } else if ($scope.PostOpObj.IsAllActionCheckListCheckedGoal == 1) {
                $scope.PostOpObj.IsAllActionCheckListCheckedGoal = null;
                angular.forEach($scope.PostOpObj.MasterAscPatientGoal, function (item) {
                    item.Value = "";
                    item.ASCPatientGoalId = item.ASCPatientGoalId || null;
                    if (item.ASCPatientGoalId != null) {
                        item.DeleteInd = "Y";
                    }
                });
            }

        }
        if (val === 2) {
            if ($scope.PostOpObj.IsAllActionCheckListCheckedGoal == null || $scope.PostOpObj.IsAllActionCheckListCheckedGoal == 1) {
                $scope.PostOpObj.IsAllActionCheckListCheckedGoal = 2;
                angular.forEach($scope.PostOpObj.MasterAscPatientGoal, function (item) {
                    item.Value = "No";
                });
            } else if ($scope.PostOpObj.IsAllActionCheckListCheckedGoal == 2) {
                $scope.PostOpObj.IsAllActionCheckListCheckedGoal = null;
                angular.forEach($scope.PostOpObj.MasterAscPatientGoal, function (item) {
                    item.Value = "";
                    item.ASCPatientGoalId = item.ASCPatientGoalId || null;
                    if (item.ASCPatientGoalId != null) {
                        item.DeleteInd = "Y";
                    }
                });
            }
        }
    };

    $scope.OnclickGoalValue = function (obj, val) {
        if (val === "Yes") {
            if (obj.Value == "Yes") {
                obj.Value = "";
                obj.ASCPatientGoalId = obj.ASCPatientGoalId || null;
                if (obj.ASCPatientGoalId != null) {
                    obj.DeleteInd = "Y";
                }
            } else if (obj.Value == "No" || obj.Value == "") {
                obj.Value = "Yes";
                obj.DeleteInd = "N";
            }

            let tempArray = $filter('filter')($scope.PostOpObj.MasterAscPatientGoal, { 'Value': "Yes" }, true);

            if (tempArray.length === $scope.PostOpObj.MasterAscPatientGoal.length) {
                $scope.PostOpObj.IsAllActionCheckListCheckedGoal = 1;
            } else {
                $scope.PostOpObj.IsAllActionCheckListCheckedGoal = null;
            }

        }

        if (val === "No") {
            if (obj.Value == "No") {
                obj.Value = "";
                obj.ASCPatientGoalId = obj.ASCPatientGoalId || null;
                if (obj.ASCPatientGoalId != null) {
                    obj.DeleteInd = "Y";
                }
            } else if (obj.Value == "Yes" || obj.Value == "") {
                obj.Value = "No";
                obj.DeleteInd = "N";
            }
            let tempArray = $filter('filter')($scope.PostOpObj.MasterAscPatientGoal, { 'Value': "No" }, true);

            if (tempArray.length === $scope.PostOpObj.MasterAscPatientGoal.length) {
                $scope.PostOpObj.IsAllActionCheckListCheckedGoal = 2;
            } else {
                $scope.PostOpObj.IsAllActionCheckListCheckedGoal = null;
            }
        }
    };

