    function compareAnestialVitals(original, edited) {
        let count = 0;
        var Affecteditem = '';
        var OldAffecteditem = '';
        if (edited.length > 0) {
            const changedItems = edited
                .filter(item => item.DeleteInd === 'N') // filter only non-deleted items
                .sort((a, b) => a.PostOPAnesthesiaVitalsId - b.PostOPAnesthesiaVitalsId)
                .filter(item => {
                    const oldItem = original.find(old => old.PostOPAnesthesiaVitalsId === item.PostOPAnesthesiaVitalsId);
                    return oldItem && (oldItem.Value !== item.Value);
                });

            if (changedItems.length > 0) {
                OldAffecteditem = changedItems
                    .map((item, index) => `${item.VitalName}: ${item.Value}`)
                    .join(', ');
            }
        }

        if (original.length > 0) {
            const changedItems = original
                .filter(item => item.DeleteInd === 'N') // filter only non-deleted items
                .sort((a, b) => a.PostOPAnesthesiaVitalsId - b.PostOPAnesthesiaVitalsId)
                .filter(item => {
                    if (!item.PostOPAnesthesiaVitalsId) {
                        return true;
                    }
                    const oldItem = edited.find(old => old.PostOPAnesthesiaVitalsId === item.PostOPAnesthesiaVitalsId);
                    return oldItem && (oldItem.Value !== item.Value);
                });

            if (changedItems.length > 0) {
                Affecteditem = changedItems
                    .map((item, index) => `${item.VitalName}: ${item.Value}`)
                    .join(', ');
            }
        }
        //if ($scope.PostOpObj.PostOpAnesthesiaNotes != $scope.LogObj.PostOpAnesthesiaNotes) {
        //    count++;
        //    if ($scope.PostOpObj.PostOpAnesthesiaNotes)
        //        Affecteditem += `${Affecteditem ? '\n ' : ''}PostOp-Anesthesia Notes :${$scope.PostOpObj.PostOpAnesthesiaNotes}`;
        //    if ($scope.LogObj.PostOpAnesthesiaNotes)
        //        OldAffecteditem += `${OldAffecteditem ? '\n ' : ''}PostOp-Anesthesia Notes :${$scope.LogObj.PostOpAnesthesiaNotes}`;

        //}
        if ($scope.PostOpObj.IsPatientDischarge != $scope.LogObj.IsPatientDischarge) {
            count++;
            if ($scope.PostOpObj.IsPatientDischarge)
                Affecteditem += `${Affecteditem ? '\n ' : ''}Patient is okay and ready for discharge`;
            if ($scope.LogObj.IsPatientDischarge)
                OldAffecteditem += `${OldAffecteditem ? '\n ' : ''}Patient is okay and ready for discharge`;

        }

        original.forEach(function (editedItem) {
            editedItem.Value = editedItem.Value || "";
            var savedItem = edited.filter(function (item) {
                item.Value = item.Value || "";
                return (item.VitalsId === editedItem.VitalId) && (item.VitalSlotTime == editedItem.VitalSlotTime) && (item.Value == editedItem.Value) && (item.DeleteInd == editedItem.DeleteInd);
            }) || [];
            if (savedItem.length == 0) {

                count++;
            }


        });

        if ($scope.PostOpObj.InTime != $scope.LogObj.InTime) {
            count++;
        }
        if ($scope.PostOpObj.OutTime != $scope.LogObj.OutTime) {
            count++;
        }
        if ($scope.AnesthesiaObj.StartTime != $scope.LogObj.StartTime) {
            count++;
        }


        $scope.AldreteTotalScoreDetails.forEach(function (editedItem) {
            editedItem.TotalScore = editedItem.TotalScore || "";
            var savedItem = $scope.LogObj.AldreteTotalScoreDetails.filter(function (item) {
                item.TotalScore = item.TotalScore || "";
                return (item.AldreteSlotTime == editedItem.AldreteSlotTime) && (item.TotalScore == editedItem.TotalScore) && (item.DeleteInd == editedItem.DeleteInd);
            }) || [];
            if (savedItem.length == 0) {

                count++;
            }


        });

        if (count != 0) {
            let obj = {
                "LogId": 0,
                "ModuleId": 2,
                "ModuleName": "ASC",
                "SubModuleId": 11,
                "SubModuleName": "Post-Op",
                "ScreenType": "Anesthesia Actions",
                "ActionType": "Edited",
                "OldActionDescription": OldAffecteditem,
                "NewActionDescription": Affecteditem,
                // "ActionDescription": `Anesthesia Actions in Post-Op Anesthesia  for Appointment ID: ${$scope.cacheStorageItem.AppointmentId}`,
                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
            };
            $scope.LogObj.LogArray.push(obj);
        }
    }
