    function formatVitalTime(timeStr) {
        if (!timeStr) return '';
        return moment(timeStr, 'HH:mm').format('hh:mm A');
    }

    function buildVitalsLines(arr) {
        let vitalsByTime = {};

        arr.forEach(v => {
            if (v.DeleteInd !== 'N') return;

            let val = (v.Value !== null && v.Value !== undefined)
                ? String(v.Value).trim() : '';
            if (val === '') return; // skip empty/default rows

            let timeKey = v.VitalSlotTime;
            if (!timeKey) return;

            if (!vitalsByTime[timeKey]) vitalsByTime[timeKey] = [];
            vitalsByTime[timeKey].push({
                name: v.VitalName,
                display: `${v.VitalName} : ${val}`
            });
        });

        // Sort by 24hr timeKey (correct sort), display as 12hr
        return Object.keys(vitalsByTime)
            .sort() // "07:05" < "12:13" — 24hr sorts correctly as string
            .map(timeKey => {
                let sorted = vitalsByTime[timeKey]
                    .sort((a, b) => a.name.localeCompare(b.name))
                    .map(x => x.display);
                let displayTime = formatVitalTime(timeKey); // "07:05" → "07:05 AM"
                return `VitalTime : ${displayTime}, ${sorted.join(', ')}`;
            });
    }


    function compareVitals(newVitals, savedVitals) {

        // ── STEP 1: DELETE case ───────────────────────────────────────────────────
        // Find rows user deleted (DeleteInd=Y) that actually exist in DB
        let deletedVitals = newVitals.filter(v => {
            if (v.DeleteInd !== 'Y') return false;
            if (!v.PostOPAnesthesiaVitalsId) return false; // never saved — not a real delete
            return savedVitals.some(s =>
                s.PostOPAnesthesiaVitalsId === v.PostOPAnesthesiaVitalsId
            );
        });

        if (deletedVitals.length > 0) {
            // Group deleted vitals by time slot for display
            let deletedByTime = {};
            deletedVitals.forEach(v => {
                let timeKey = v.VitalSlotTime;
                if (!timeKey) return;
                let val = (v.Value !== null && v.Value !== undefined)
                    ? String(v.Value).trim() : '';
                if (val === '') return;
                if (!deletedByTime[timeKey]) deletedByTime[timeKey] = [];
                deletedByTime[timeKey].push(`${v.VitalName} : ${val}`);
            });

            let deletedLines = Object.keys(deletedByTime)
                .sort()
                .map(timeKey => {
                    let displayTime = formatVitalTime(timeKey);
                    return `VitalTime : ${displayTime}, ${deletedByTime[timeKey].join(', ')}`;
                });

            let OldValue = deletedLines.join('\n');
            if (OldValue) {
                $scope.LogObj.LogArray.push({
                    LogId: 0,
                    ModuleId: 2,
                    ModuleName: 'ASC',
                    SubModuleId: 11,
                    SubModuleName: 'Post-Op',
                    ScreenType: 'Anesthesia Actions',
                    ActionType: 'Deleted',
                    OldActionDescription: OldValue,
                    NewActionDescription: '',
                    ActionDateTime: $filter('date')(new Date(), 'yyyy-MM-dd HH:mm:ss'),
                });
            }
        }

        // Collect deleted IDs — exclude from edit diff so they don't bleed in
        let deletedIds = new Set(
            deletedVitals.map(v => v.PostOPAnesthesiaVitalsId).filter(Boolean)
        );

        // ── STEP 2: Strip deleted rows from both sides for edit comparison ─────────
        let activeNew = newVitals.filter(v =>
            v.DeleteInd !== 'Y' && !deletedIds.has(v.PostOPAnesthesiaVitalsId)
        );
        let activeSaved = savedVitals.filter(v =>
            v.DeleteInd !== 'Y' && !deletedIds.has(v.PostOPAnesthesiaVitalsId)
        );

        // ── STEP 3: Row-by-row diff ───────────────────────────────────────────────
        let changedOldRows = []; // saved DB rows whose value changed
        let changedNewRows = []; // same rows with new UI values
        let addedRows = []; // new rows not yet in DB
        let removedRows = []; // rows in DB but gone from UI

        // Find changed and added rows
        activeNew.forEach(newRow => {
            let val = (newRow.Value !== null && newRow.Value !== undefined)
                ? String(newRow.Value).trim() : '';
            //if (val === '') return; // skip empty/default rows — user never typed

            if (val === '') {
                // ✅ NEW: if old row had a value, treat as cleared/removed
                if (newRow.PostOPAnesthesiaVitalsId) {
                    let oldRow = activeSaved.find(o =>
                        o.PostOPAnesthesiaVitalsId === newRow.PostOPAnesthesiaVitalsId
                    );
                    let oldVal = oldRow && (oldRow.Value !== null && oldRow.Value !== undefined)
                        ? String(oldRow.Value).trim() : '';
                    if (oldRow && oldVal !== '') {
                        removedRows.push(oldRow); // log it as removed
                    }
                }
                return;
            }

            if (!newRow.PostOPAnesthesiaVitalsId) {
                // Brand new row — no ID means never saved
                addedRows.push(newRow);
                return;
            }

            // Find matching saved row by ID
            let savedRow = activeSaved.find(s =>
                s.PostOPAnesthesiaVitalsId === newRow.PostOPAnesthesiaVitalsId
            );

            if (!savedRow) {
                // Has ID but not found in saved — treat as added
                addedRows.push(newRow);
                return;
            }

            let savedVal = (savedRow.Value !== null && savedRow.Value !== undefined)
                ? String(savedRow.Value).trim() : '';
            let savedTime = savedRow.VitalSlotTime || '';
            let newTime = newRow.VitalSlotTime || '';

            if (savedVal !== val || savedTime !== newTime || savedRow.VitalName !== newRow.VitalName) {
                changedOldRows.push(savedRow); // what it WAS
                changedNewRows.push(newRow);   // what it IS NOW
            }
            // Completely unchanged rows → skip (this was the original bug)
        });

        // Find removed rows — in savedVitals but completely missing from activeNew
        activeSaved.forEach(savedRow => {
            let stillExists = activeNew.find(n =>
                n.PostOPAnesthesiaVitalsId === savedRow.PostOPAnesthesiaVitalsId
            );
            if (!stillExists) removedRows.push(savedRow);
        });

        // ── STEP 4: Check if there are any edit changes ───────────────────────────
        let hasVitalChanges =
            changedOldRows.length > 0 ||
            changedNewRows.length > 0 ||
            addedRows.length > 0 ||
            removedRows.length > 0;

        // Also check time field changes
        $scope.PostOpObj.InTime = $scope.PostOpObj.InTime || '';
        $scope.LogObj.InTime = $scope.LogObj.InTime || '';
        $scope.PostOpObj.OutTime = $scope.PostOpObj.OutTime || '';
        $scope.LogObj.OutTime = $scope.LogObj.OutTime || '';
        $scope.AnesthesiaObj.StartTime = $scope.AnesthesiaObj.StartTime || '';
        $scope.LogObj.StartTime = $scope.LogObj.StartTime || '';

        let hasTimeChanges =
            $scope.PostOpObj.InTime !== $scope.LogObj.InTime ||
            $scope.PostOpObj.OutTime !== $scope.LogObj.OutTime ||
            $scope.AnesthesiaObj.StartTime !== $scope.LogObj.StartTime;

        // Check Aldrete changes
        let hasAldreteChanges = false;
        ($scope.AldreteTotalScoreDetails || []).forEach(newItem => {
            newItem.TotalScore = newItem.TotalScore || '';
            let match = ($scope.LogObj.AldreteTotalScoreDetails || []).find(s =>
                s.AldreteSlotTime === newItem.AldreteSlotTime &&
                s.TotalScore === newItem.TotalScore &&
                s.DeleteInd === newItem.DeleteInd
            );
            if (!match) hasAldreteChanges = true;
        });

        if (!hasVitalChanges && !hasTimeChanges && !hasAldreteChanges) {
            return; // Nothing changed — no edit log needed
        }

        // ── STEP 5: Build OldValue and NewValue from ONLY changed rows ────────────
        let oldLines = buildVitalsLines([...changedOldRows, ...removedRows]);
        let newLines = buildVitalsLines([...changedNewRows, ...addedRows]);

        let OldValue = oldLines.join('\n');
        let NewValue = newLines.join('\n');

        // ── STEP 6: Push Edited log entry ────────────────────────────────────────
        if (OldValue || NewValue) {
            $scope.LogObj.LogArray.push({
                LogId: 0,
                ModuleId: 2,
                ModuleName: 'ASC',
                SubModuleId: 11,
                SubModuleName: 'Post-Op',
                ScreenType: 'Anesthesia Actions',
                ActionType: 'Edited',
                OldActionDescription: OldValue,
                NewActionDescription: NewValue,
                ActionDateTime: $filter('date')(new Date(), 'yyyy-MM-dd HH:mm:ss'),
            });
        }
    }




