    $scope.PostOpselectedItem = function (subArray, item,mainitem) {
        if (mainitem.CheckListCode == 136 ) {
            if (item.IsChecked == true) {
                item.IsChecked = false;
                item.PatientAscCheckListDetailId = item.PatientAscCheckListDetailId || null;
                if (item.PatientAscCheckListDetailId != null) {
                    item.DeleteInd = "Y";
                }
            } else {
                item.IsChecked = true;
            }
        } else {
            if (item.IsChecked == true) {
                angular.forEach(subArray, function (sitem) {
                    sitem.IsChecked = false;

                });
                item.PatientAscCheckListDetailId = item.PatientAscCheckListDetailId || null;
                if (item.PatientAscCheckListDetailId != null) {
                    item.DeleteInd = "Y";
                }
                if (mainitem.CheckListCode == 124) {
                    mainitem.IsChecked = false;
                    mainitem.Value = item.Value;
                    if (mainitem.Value == 'No') {
                        mainitem.Remarks = '';
                        mainitem.shownotes = false;
                    }
                }
            } else {
                if (subArray.length > 0) {
                    angular.forEach(subArray, function (sitem) {
                        sitem.IsChecked = false;
                        if (sitem.OrganizationPreOpCheckListValueId == item.OrganizationPreOpCheckListValueId) {
                            item.IsChecked = true;
                        }
                    });
                }
                if (mainitem.CheckListCode == 124) {
                    mainitem.IsChecked = true;
                    mainitem.Value = item.Value;
                    if (mainitem.Value !== 'No') {
                        mainitem.Remarks = '';
                        mainitem.shownotes = false;
                    } else {
                        mainitem.shownotes = true;
                    }
                }
            }

            if (item.CheckListId == 241) {
                if (item.IsChecked == true && item.Value == "Yes") {
                    $scope.IsDiscontinueoxygen = true;
                } else {
                    $scope.IsDiscontinueoxygen = false;
                    $scope.PostOpObj.DiscontinueIVTime = '';
                    angular.forEach($scope.PostOpObj.PatientInterventionsList, function (sitem) {
                        if (sitem.CheckListId == 242 || sitem.CheckListId == 250) {
                            angular.forEach(sitem.OrganizationCheckListDetails, function (nitem) {
                                nitem.IsChecked = false;
                                nitem.PatientAscCheckListDetailId = nitem.PatientAscCheckListDetailId || null;
                                if (nitem.PatientAscCheckListDetailId !== null) {
                                    nitem.DeleteInd = "Y";
                                }
                            });
                        }
                    });
                }
            };
            if (mainitem.CheckListCode == 335) {
                if (item.IsChecked == true && item.Value == "Yes") {
                    $scope.CatheterRemoved = true;
                } else {
                    $scope.CatheterRemoved = false;
                    angular.forEach($scope.PostOpObj.PatientInterventionsList, function (sitem) {
                        if (sitem.CheckListCode == 257) {
                            angular.forEach(sitem.OrganizationCheckListDetails, function (nitem) {
                                nitem.IsChecked = false;
                                nitem.PatientAscCheckListDetailId = nitem.PatientAscCheckListDetailId || null;
                                if (nitem.PatientAscCheckListDetailId !== null) {
                                    nitem.DeleteInd = "Y";
                                }
                            });
                        }
                    });
                }
            };
        }
    }

    $scope.GetPostopTemplateList = function (val) {
        let reqObj = {
            "HospitalId": $scope.HospitalId,
            "UserId": $scope.UserId,
            "CheckListCategoryId": val
        }
        eHnotePatientDataService.GetPostOpCheckListTemplates(reqObj).then(function (resp) {
            if (resp.data.status="Sucess") {
                if (resp.data.rows.length > 0) {
                    if (val==4) {
                        let CheckoutChecklistTemplateList = $filter('filter')(resp.data.rows, { 'CheckListCategoryId': 4 }, true) || []
                        $scope.PostOpObj.CheckoutChecklistTemplateList = angular.copy(CheckoutChecklistTemplateList);

                        $scope.PostOpObj.CheckoutChecklistTemplateList = $filter('filter')(CheckoutChecklistTemplateList, { 'CheckListSubTypeId': 3 }, true) || []
                        $scope.PostOpObj.ProgressNotesTemplateList = $filter('filter')(CheckoutChecklistTemplateList, { 'CheckListSubTypeId': 18 }, true) || []
                    }
                    if (val==1) {
                        let CheckinChecklistTemplateList = $filter('filter')(resp.data.rows, { 'CheckListCategoryId': 1 }, true) || []
                        $scope.PostOpObj.CheckinChecklistTemplateList = angular.copy(CheckinChecklistTemplateList);
                    }


                } else {
                    $scope.PostOpObj.CheckinChecklistTemplateList = [];
                    $scope.PostOpObj.CheckoutChecklistTemplateList = [];
                    $scope.PostOpObj.ProgressNotesTemplateList = [];
                }
            }
        });
    }


    $scope.OrdersInit = function (MedTypeId) {
        let FinalOrderDetails = $filter('filter')($scope.PostOpObj.OrderDetails, { 'MedTypeId': MedTypeId}, true) || [];
        if (FinalOrderDetails.length > 0) {
            angular.forEach(FinalOrderDetails, function (Mitem) {
                let temp = $filter('filter')(Mitem.PostOpMedications, { 'DeleteInd': 'N' }, true) || [];
                let temp1 = $filter('filter')(Mitem.GeneralOrders, { 'DeleteInd': 'N' }, true) || [];
                if (temp.length == 0 && temp1.length == 0) {
                    Mitem.DeleteInd = 'Y';
                }
            });
        }
    }

    $scope.updateSurgeonOrderCheckbox = function (Type) {

        if (Type == 'PostOpMedications') {
            let activeOrders = ($scope.PostOpObj.OrderDetails || [])
                .filter(order => order.DeleteInd === 'N' && order.MedTypeId == 5);

            if (activeOrders.length === 0) {
                $scope.PostOpObj.DisablePostOpSurgeonCheck = false;
                return;
            }

            let isAllDeleted = activeOrders.every(order => {

                let dilation = order.PostOpMedications || [];

                let noActiveDilation =
                    dilation.length === 0 ||
                    dilation.every(item => item.DeleteInd === 'Y');

                return noActiveDilation;
            });

            $scope.PostOpObj.DisablePostOpSurgeonCheck = !isAllDeleted;
        }
        else if (Type == 'PostOpAnesthesiaMedications') {
            let activeOrders = ($scope.PostOpObj.OrderDetails || [])
                .filter(order => order.DeleteInd === 'N' && order.MedTypeId == 8);

            if (activeOrders.length === 0) {
                $scope.PostOpObj.DisablePostOpAnesthesiaCheck = false;
                return;
            }

            let isAllDeleted = activeOrders.every(order => {

                let dilation = order.PostOpMedications || [];

                let noActiveDilation =
                    dilation.length === 0 ||
                    dilation.every(item => item.DeleteInd === 'Y');

                return noActiveDilation;
            });

            $scope.PostOpObj.DisablePostOpAnesthesiaCheck = !isAllDeleted;
        }
    };

    $scope.DeleteMainMediacation = function (item, Aitem, Type) {

        var index = Aitem.PostOpMedications.indexOf(item);
        if (item.AscMedicationId != 0) {
            alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure you want to Delete?</h4>", function () {
                if (index > -1) {
                    item.DeleteInd = 'Y';
                }
                $scope.updateSurgeonOrderCheckbox(Type);
                $scope.$digest();
                $scope.OrdersInit(Aitem.MedTypeId);
            }, function () {

            });
        }
        else {
            if (index > -1) {
                Aitem.PostOpMedications.splice(index, 1);

            }
            $scope.updateSurgeonOrderCheckbox(Type);
        }

        $scope.OrdersInit(Aitem.MedTypeId);
    }

