            let pulseImg = new Image();
            pulseImg.src = 'img/Pulse.svg';

            let respRateImg = new Image();
            respRateImg.src = 'img/respRate.svg';

            let SpO2Img = new Image();
            SpO2Img.src = 'img/SPO2.svg';

            let O2SatImg = new Image();
            O2SatImg.src = 'img/O2Saturation.svg';

            let EKGImg = new Image();
            EKGImg.src = 'img/ECG.svg';

            let ETCO2Img = new Image();
            ETCO2Img.src = 'img/ECO2.svg';

            let TempImg = new Image();
            TempImg.src = 'img/respRate.svg';

            let SystolicVitalsArray = $filter('filter')($scope.AnesthetistVitals, { 'VitalId': 1 }, true);
