    $scope.AddUpdateOrderTemplate = function (MedTypeId, MedType) {

        if (MedTypeId == 5) {
            if ($scope.PostOpTemplateobj.TemplateName == '') {
                alertify.error("Please enter template name!");
                return false;
            }

            $scope.templateReq = {
                "UserId": $scope.UserId || "",
                "HospitalId": $scope.HospitalId || "",
                "RoleId": $scope.RoleId || null,
                "TemplateId": 0,
                "TemplateName": $scope.PostOpTemplateobj.TemplateName || "",
                "DeleteInd": "N",
                "ScreenType": "PostOp",
                "ScreenTypeId": 6,
                "MedTypeId": MedTypeId,
                "MedTypeName": MedType,
                "DilationMedications": [],
                "GeneralOrders": [],
                "PreOpMedications": [],
                "PostOpMedications": [],
            };



            let FinalOrderDetails = [];
            FinalOrderDetails = $filter('filter')(angular.copy($scope.PostOpObj.OrderDetails), { 'MedTypeId': 5 }, true) || [];
            var count = 0
            angular.forEach(FinalOrderDetails, function (Mitem) {
                let templist = $filter("filter")(Mitem.PostOpMedications, { "DeleteInd": 'N' }, true) || [];
                let templist1 = $filter("filter")(Mitem.GeneralOrders, { "DeleteInd": 'N' }, true) || [];
                if (templist.length !== 0 || templist1.length !== 0) {
                    count++;
                }
            });
            if (count == 0) {
                alertify.error("Please add any orders data!");
                return false;
            }
            if (FinalOrderDetails.length > 0) {
                angular.forEach(FinalOrderDetails, function (Mitem) {
                    if (Mitem.PostOpMedications.length > 0) {
                        angular.forEach(Mitem.PostOpMedications, function (item) {
                            item.IsPostOpMed = true;
                            item.UserType = "Nurse";
                            item.DropTimings = [];
                            if (item.DeleteInd == 'N') {
                                $scope.templateReq.PostOpMedications.push(item);
                            }

                        });
                    }
                    if (Mitem.GeneralOrders.length > 0) {
                        angular.forEach(Mitem.GeneralOrders, function (item) {
                            if (item.DeleteInd == 'N') {
                                $scope.templateReq.GeneralOrders.push(item);
                            }
                        });
                        //templateReq.GeneralOrders = Mitem.GeneralOrders || [];
                    }
                });
            }
        } else {
            if ($scope.PostOpTemplateobj.TemplateName == '') {
                alertify.error("Please enter template name!");
                return false;
            }

            $scope.templateReq = {
                "UserId": $scope.UserId || "",
                "HospitalId": $scope.HospitalId || "",
                "RoleId": $scope.RoleId || null,
                "TemplateId": 0,
                "TemplateName": $scope.PostOpTemplateobj.TemplateName || "",
                "DeleteInd": "N",
                "ScreenType": "PostOp",
                "ScreenTypeId": 6,
                "MedTypeId": MedTypeId,
                "MedTypeName": MedType,
                "DilationMedications": [],
                "GeneralOrders": [],
                "PreOpMedications": [],
                "PostOpMedications": [],
            };



            let FinalOrderDetails = [];
            FinalOrderDetails = $filter('filter')(angular.copy($scope.PostOpObj.OrderDetails), { 'MedTypeId': 8 }, true) || [];
            var count = 0
            angular.forEach(FinalOrderDetails, function (Mitem) {
                let templist = $filter("filter")(Mitem.PostOpMedications, { "DeleteInd": 'N' }, true) || [];
                let templist1 = $filter("filter")(Mitem.GeneralOrders, { "DeleteInd": 'N' }, true) || [];
                if (templist.length !== 0 || templist1.length !== 0) {
                    count++;
                }
            });
            if (count == 0) {
                alertify.error("Please add any orders data!");
                return false;
            }
            if (FinalOrderDetails.length > 0) {
                angular.forEach(FinalOrderDetails, function (Mitem) {
                    if (Mitem.PostOpMedications.length > 0) {
                        angular.forEach(Mitem.PostOpMedications, function (item) {
                            item.IsPostOpMed = true;
                            item.UserType = "Anesthesia";
                            item.DropTimings = [];
                            if (item.DeleteInd == 'N') {
                                $scope.templateReq.PostOpMedications.push(item);
                            }

                        });
                    }
                    if (Mitem.GeneralOrders.length > 0) {
                        angular.forEach(Mitem.GeneralOrders, function (item) {
                            if (item.DeleteInd == 'N') {
                                $scope.templateReq.GeneralOrders.push(item);
                            }
                        });
                    }
                });
            }
        }

        //console.log(JSON.stringify(templateReq));
        //return false;
        eHnoteSurgeryService.AddUpdateAscUserOrderTemplates($scope.templateReq).then(function (resp) {
            if (resp.data.status === "Success") {
                alertify.success("Template saved successfully!");
                $scope.GetOrderTemplates();
                $scope.PostOpTemplateobj.IsOpenOrderTemplate = false;
                $scope.PostOpTemplateobj.IsOpenAnesthesiaOrderTemplate = false;
                $scope.PostOpTemplateobj.TemplateName = '';

            }
            if (resp.data.status === "Failure") {
                alertify.error('TemplateName Already Exists')
            }
        }, function (err) {
            console.log(err);
        });

    };

