    $scope.AddPostopAnesthesiaMedication = function () {
        $scope.PostOpMedicationAnsthesia = true;
        let item = $scope.PostOpMedicationAnesthesiaObj.MedicineObject;


        if (!item || !item.OrganizationPrescriptionId) {
            alertify.error('Please select a Medicine');
            return false;
        }

        if ($scope.PostOpMedicationAnesthesiaObj.OrderTypeName == "" && $scope.PostOpMedicationAnesthesiaObj.OrderTypeId == null) {
            OrderTypeId = 2;
            OrderTypeName = "Live Medications";
        } else {
            OrderTypeId = $scope.PostOpMedicationAnesthesiaObj.OrderTypeId;
            OrderTypeName = $scope.PostOpMedicationAnesthesiaObj.OrderTypeName;
        }

        let obj = {
            "AscMedicationId": item.AscMedicationId || 0,
            "OrganizationMedicationId": item.OrganizationPrescriptionId,
            "OrganizationPrescriptionId": item.OrganizationPrescriptionId,
            "ParentOrganizationId": $scope.ParenthospitalId,
            "ASCOrganizationMedicationId": 0,
            "Strength": item.Strength || '',
            "IsFrequent": item.IsFrequent || 'N',
            "MedicineId": item.MedicineId,
            "MedicationName": $scope.PostOpMedicationAnesthesiaObj.MedicationName,

            "Action": $scope.PostOpMedicationAnesthesiaObj.Action,
            "Dose": $scope.PostOpMedicationAnesthesiaObj.Dose,
            "DoseUnit": $scope.PostOpMedicationAnesthesiaObj.DoseUnit,
            "Route": $scope.PostOpMedicationAnesthesiaObj.Route,
            "Frequency": $scope.PostOpMedicationAnesthesiaObj.Frequency,

            "ActionId": $scope.PostOpMedicationAnesthesiaObj.ActionId,
            "DoseId": $scope.PostOpMedicationAnesthesiaObj.DoseId,
            "DoseUnitId": $scope.PostOpMedicationAnesthesiaObj.DoseUnitId,
            "RouteId": $scope.PostOpMedicationAnesthesiaObj.RouteId,
            "FrequencyId": $scope.PostOpMedicationAnesthesiaObj.FrequencyId,
            "OrderDescription": $scope.PostOpMedicationAnesthesiaObj.OrderDescription,
            "MedicationNotes": $scope.PostOpMedicationAnesthesiaObj.MedicationNotes,
            "maxDose": $scope.PostOpMedicationAnesthesiaObj.maxDose,
            "IsChecked": false,
            "IsDilationMed": false,
            "IsIntraAnesthesiaMed": false,
            "IsIntraMed": true,
            "IsPreOPMed": false,
            "MedicationDosage": "",
            "DropTimings": $scope.PostOpMedicationAnesthesiaObj.DropTimings ||  [],
            "TypeId": 4,
            "DeleteInd": "N",
            "OrderTypeId": OrderTypeId,
            "OrderTypeName": OrderTypeName,

        };


        let templist = $filter("filter")($scope.PostOpObj.OrderDetails, function (oitem) {
            return oitem.MedTypeId === 8 && oitem.IsOrderReviewed === false && oitem.DeleteInd === 'N' && oitem.OrderTypeId === OrderTypeId;
        }) || [];






        if (templist.length > 0 && templist[0].PostOpMedications.length > $scope.PostOpMedicationAnesthesiaObj.EditIndex && $scope.PostOpMedicationAnesthesiaObj.EditIndex >= 0) {
            templist[0].PostOpMedications[$scope.PostOpMedicationAnesthesiaObj.EditIndex] = obj;
            alertify.success('Updated successfully');
        }

        else {
            if (templist.length > 0) {
                templist[0].PostOpMedications.push(obj);
            } else {

                let newObj = {
                    "UserOrderId": 0,
                    "UserId": $scope.UserId,
                    "DeleteInd": "N",
                    "ReviewedBy": null,
                    "IsOrderReviewed": false,
                    "ReviewedByDateTime": null,
                    "ReviewedByPassword": '',
                    "UserType": "Nurse",
                    "ScreenType": "PostOp",
                    "ScreenTypeId": 6,
                    "MedTypeId": 8,
                    "MedTypeName": "Postop Anesthesia Medications",

                    "PostOpMedications": [obj],
                    "GeneralOrders": [],
                    "OrderTypeId": 2,
                    "OrderTypeName": "Live Medications"
                };
                $scope.PostOpObj.OrderDetails.push(newObj);
            }
            alertify.success('Added successfully');
        }

        let activeOrders = ($scope.PostOpObj.OrderDetails || [])
            .filter(order => order.DeleteInd === 'N' && order.MedTypeId == 8);

        let isColumnTrue = activeOrders.some(order =>
            (order.PostOpMedications &&
                order.PostOpMedications.some(item => item.DeleteInd === 'N'))
        );

        $scope.PostOpObj.DisablePostOpAnesthesiaCheck = isColumnTrue;
        $scope.PostOpObj.IsPostOpAnesthesiaOrdersTimeAdded = !isColumnTrue;

        $scope.PostOpMedicationAnesthesiaObj = angular.copy($scope.GetPostOpMedicationObj());
    }


