    $scope.ShowTimer = function (StartTimerTime, DurationInMinutes) {
        var StartTime = StartTimerTime || '';
        var Duration = (parseFloat(DurationInMinutes) || 0) * 60 * 1000; // convert minutes to ms
        if (DurationInMinutes !== '') {
            const interval = $interval(function () {
                if ($scope.PostOpObj.IsForceEarlySignOff) {
                    $scope.PostOpObj.IsShowForceEarlySignOffButton = false;
                    $scope.PostOpObj.IsTimerStoped = true;
                    $scope.PostOpObj.DischargeTimerStartTime = $scope.PostOpObj.DischargeSignOffEndTime;
                } else {
                    const now = new Date();
                    var todayString = now.toDateString(); // e.g., "Mon Nov 11 2025"
                    var startTimer = new Date(todayString + ' ' + StartTime);
                    const diff = now - startTimer; // elapsed time in ms

                    // if elapsed >= given duration, stop timer
                    if (Duration > 0 && diff >= Duration) {
                        $scope.PostOpObj.DischargeTimerStartTime = $scope.PostOpObj.DischargeSignOffEndTime;
                        $scope.PostOpObj.IsTimerStoped = true;
                        $scope.PostOpObj.IsShowForceEarlySignOffButton = false;
                        $interval.cancel(interval);
                    } else {
                        $scope.PostOpObj.DischargeTimerStartTime = diff;
                    }
                }

            }, 1000);
        }
    };

    $scope.SaveForceEarlySignOffRemarks = function () {
        $scope.PostOpObj.ForceEarlySignedOffRemarks = $scope.PostOpObj.ForceEarlySignedOffRemarks || null;
        if ($scope.PostOpObj.ForceEarlySignedOffRemarks == null) {
            alertify.error("Please Enter Remarks");
            return false;
        }
        var CurrentTime = $filter("date")(new Date(), "h:mm a");
        var Param = {
            "AppointmentID": $scope.cacheStorageItem.AppointmentId,
            "UserId": $scope.UserId,
            "HospitalId": $scope.HospitalId,
            "StartTimer": $scope.PostOpObj.DischargeSignOffStartTime,
            "EndTimer": CurrentTime,
            "Remarks": $scope.PostOpObj.ForceEarlySignedOffRemarks,
            "DischargeStartTimeUser": $scope.PostOpObj.DischargeStartTimeUser || null,
            "DischargeEndTimeUser": $scope.UserId,
            "IsForceEarlySignedOff": true,
        }

        let Value = `Forcefull Sign Off Time: ${CurrentTime} \n Remarks : ${$scope.PostOpObj.ForceEarlySignedOffRemarks}`;

        let obj = {
            "LogId": 0,
            "ModuleId": 2,
            "ModuleName": "ASC",
            "SubModuleId": 10,
            "SubModuleName": "Post-Op Nurse",
            "ScreenType": "ForceFull SignOff",
            "ActionType": "Added",
            "OldActionDescription": "",
            "NewActionDescription": Value,
            "ActionDateTime": moment().format("YYYY-MM-DD HH:mm:ss"),
        };

        $scope.AddAuditLogNew(obj);

        eHnoteSurgeryService.AddUpdateDischargeSignOffTimer(Param).then(function (response) {
            if (response.data.Status === "Success") {
                $scope.PostOpObj.IsShowForceEarlySignOffPopover = false;
                $scope.GetPostOpChartData();
            }
            if (response.data.Status === 'Failure') {
                alertify.error(response.data.Message);
            }
        })
    };

